// Strict JSON reader. Unknown prompt fields are scanned without allocating their content.
internal sealed class FastJson {
 readonly string s; int p; int depth;
 FastJson(string text){s=text;}
 void White(){while(p<s.Length && (s[p]==' '||s[p]=='\t'||s[p]=='\r'||s[p]=='\n'))p++;}
 void Expect(char c){White();if(p==s.Length||s[p++]!=c)throw new System.FormatException("JSON 格式错误。");}
 string String(bool keep){Expect('"');var b=keep?new System.Text.StringBuilder():null;while(p<s.Length){char c=s[p++];if(c=='"')return keep?b.ToString():null;if(c<32)throw new System.FormatException("JSON 控制字符错误。");if(c=='\\'){if(p==s.Length)break;char e=s[p++];switch(e){case '"':case '\\':case '/':c=e;break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':if(p+4>s.Length)throw new System.FormatException();int n=0;for(int i=0;i<4;i++){char h=s[p++];int v=h>='0'&&h<='9'?h-'0':h>='a'&&h<='f'?h-'a'+10:h>='A'&&h<='F'?h-'A'+10:-1;if(v<0)throw new System.FormatException();n=(n<<4)|v;}c=(char)n;break;default:throw new System.FormatException("JSON 转义错误。");}}if(keep)b.Append(c);}throw new System.FormatException("JSON 字符串不完整。");}
 object Value(bool keep){White();if(p==s.Length||++depth>64)throw new System.FormatException();object result=null;char c=s[p];if(c=='"')result=String(keep);else if(c=='{')result=Object(keep);else if(c=='['){p++;White();if(p<s.Length&&s[p]==']')p++;else{while(true){Value(false);White();if(p<s.Length&&s[p]==']'){p++;break;}Expect(',');}}}else{int start=p;while(p<s.Length&&s[p]!=','&&s[p]!=']'&&s[p]!='}'&&!char.IsWhiteSpace(s[p]))p++;string token=s.Substring(start,p-start);if(token!="null"&&token!="true"&&token!="false"&&!System.Text.RegularExpressions.Regex.IsMatch(token,@"\A-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?\z"))throw new System.FormatException("JSON 值错误。");}depth--;return result;}
 System.Collections.Generic.Dictionary<string,object> Object(bool keep){Expect('{');var d=keep?new System.Collections.Generic.Dictionary<string,object>():null;var keys=new System.Collections.Generic.HashSet<string>();White();if(p<s.Length&&s[p]=='}'){p++;return d;}while(true){string key=String(true);if(!keys.Add(key))throw new System.FormatException("JSON 字段重复。");Expect(':');bool needed=keep&&(key=="session_id"||key=="model"||key=="transcript_path"||key=="type"||key=="payload"||key=="id"||key=="model_provider");object v=Value(needed);if(needed)d.Add(key,v);White();if(p<s.Length&&s[p]=='}'){p++;return d;}Expect(',');}}
 public static System.Collections.Generic.Dictionary<string,object> Read(string s){var r=new FastJson(s);var d=r.Object(true);r.White();if(r.p!=s.Length)throw new System.FormatException("JSON 尾部错误。");return d;}
 public static string Quote(string s){var b=new System.Text.StringBuilder("\"");foreach(char c in s){if(c=='"'||c=='\\')b.Append('\\').Append(c);else if(c<32||c>126)b.Append("\\u").Append(((int)c).ToString("x4"));else b.Append(c);}return b.Append('"').ToString();}
}
